import React, { useState } from "react";
import { StoryCase, Hypothesis } from "../types";
import { soundController } from "../utils/audioSynth";
import { 
  ArrowRight, 
  MapPin, 
  Clock, 
  Search, 
  Lightbulb, 
  CheckCircle2, 
  XCircle, 
  Sparkles, 
  Send, 
  BookMarked, 
  HelpCircle,
  FileText,
  UserCheck,
  ChevronDown,
  ChevronUp,
  BrainCircuit,
  RotateCcw
} from "lucide-react";

interface CaseReaderProps {
  storyCase: StoryCase;
  onBack: () => void;
  onSolveCase: (score: number, verdict: string, userTheory?: string) => void;
  isAlreadySolved?: boolean;
}

export const CaseReader: React.FC<CaseReaderProps> = ({
  storyCase,
  onBack,
  onSolveCase,
  isAlreadySolved = false,
}) => {
  const [selectedHypothesis, setSelectedHypothesis] = useState<Hypothesis | null>(null);
  const [revealedClues, setRevealedClues] = useState<Record<string, boolean>>({});
  const [revealedHint, setRevealedHint] = useState<string | null>(null);
  const [isLoadingHint, setIsLoadingHint] = useState(false);
  const [fontSize, setFontSize] = useState<"md" | "lg" | "xl">("lg");
  const [customTheory, setCustomTheory] = useState("");
  const [isEvaluatingAi, setIsEvaluatingAi] = useState(false);
  const [aiEvaluation, setAiEvaluation] = useState<{
    isCorrect: boolean;
    score: number;
    verdict: string;
    feedback: string;
    cognitivePointsEarned: number;
    brainAlertnessBoost: string;
  } | null>(null);

  const toggleClue = (id: string) => {
    soundController.playSfx("clue");
    setRevealedClues(prev => ({ ...prev, [id]: !prev[id] }));
  };

  const handleSelectHypothesis = (hyp: Hypothesis) => {
    soundController.playSfx("click");
    setSelectedHypothesis(hyp);
    if (hyp.isCorrect) {
      soundController.playSfx("success");
      onSolveCase(90, "استنتاج ثاقب وحاسم");
    } else {
      soundController.playSfx("wrong");
    }
  };

  const handleFetchAiHint = async () => {
    if (revealedHint) return;
    setIsLoadingHint(true);
    soundController.playSfx("click");
    try {
      const res = await fetch("/api/story/hint", {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({
          storyTitle: storyCase.title,
          puzzleQuestion: storyCase.puzzleQuestion,
          clues: storyCase.clues,
          userThoughts: "أحتاج لمفتاح منطقي للربط بين الأدلة",
        }),
      });
      if (!res.ok) {
        throw new Error(`HTTP error ${res.status}`);
      }
      const data = await res.json();
      setRevealedHint(data.hint || storyCase.subtleHint);
      soundController.playSfx("clue");
    } catch (e) {
      setRevealedHint(storyCase.subtleHint);
    } finally {
      setIsLoadingHint(false);
    }
  };

  const handleSubmitCustomTheory = async (e: React.FormEvent) => {
    e.preventDefault();
    if (!customTheory.trim() || isEvaluatingAi) return;

    setIsEvaluatingAi(true);
    soundController.playSfx("click");
    try {
      const correctHyp = storyCase.hypotheses.find(h => h.isCorrect);
      const res = await fetch("/api/story/evaluate-answer", {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({
          storyTitle: storyCase.title,
          storyContext: storyCase.storyContent,
          puzzleQuestion: storyCase.puzzleQuestion,
          correctRationale: correctHyp?.shortExplanation || "الربط المنطقي بين الأدلة المادية وتناقض الأقوال",
          userAnswer: customTheory,
        }),
      });
      if (!res.ok) {
        throw new Error(`HTTP error ${res.status}`);
      }
      const data = await res.json();
      setAiEvaluation(data);
      if (data.isCorrect || data.score >= 70) {
        soundController.playSfx("success");
        onSolveCase(data.score, data.verdict, customTheory);
      } else {
        soundController.playSfx("wrong");
      }
    } catch (err) {
      // Local fallback evaluation
      const hasKeywords = customTheory.length > 20;
      setAiEvaluation({
        isCorrect: hasKeywords,
        score: hasKeywords ? 85 : 50,
        verdict: hasKeywords ? "استنتاج تحليلي واعد" : "بحاجة لتدقيق الأدلة",
        feedback: "تم تسجيل استنتاجك وتطبيقه على الأدلة. استمر في فحص التناقضات المادية بدقة.",
        cognitivePointsEarned: hasKeywords ? 35 : 15,
        brainAlertnessBoost: "تنشيط مهارة التفكير الاستنباطي الحر",
      });
    } finally {
      setIsEvaluatingAi(false);
    }
  };

  const getFontSizeClass = () => {
    if (fontSize === "md") return "text-base leading-relaxed";
    if (fontSize === "xl") return "text-2xl leading-loose";
    return "text-lg md:text-xl leading-relaxed";
  };

  return (
    <div className="max-w-5xl mx-auto px-4 sm:px-6 py-6 space-y-8 animate-fadeIn">
      {/* Top Navigation & Metadata */}
      <div className="flex flex-wrap items-center justify-between gap-4 pb-4 border-b border-slate-800">
        <button
          onClick={onBack}
          className="flex items-center gap-2 text-slate-400 hover:text-amber-300 text-sm font-medium transition-colors"
        >
          <ArrowRight className="w-4 h-4" />
          <span>العودة لقائمة القضايا</span>
        </button>

        <div className="flex items-center gap-2">
          {/* Font Size controls */}
          <div className="flex items-center gap-1 bg-slate-900 border border-slate-800 rounded-lg p-1 text-xs">
            <span className="text-slate-500 px-1.5">حجم الخط:</span>
            <button
              onClick={() => setFontSize("md")}
              className={`px-2 py-0.5 rounded ${fontSize === "md" ? "bg-amber-600/30 text-amber-300 font-bold" : "text-slate-400"}`}
            >
              أ-
            </button>
            <button
              onClick={() => setFontSize("lg")}
              className={`px-2 py-0.5 rounded ${fontSize === "lg" ? "bg-amber-600/30 text-amber-300 font-bold" : "text-slate-400"}`}
            >
              عادي
            </button>
            <button
              onClick={() => setFontSize("xl")}
              className={`px-2 py-0.5 rounded ${fontSize === "xl" ? "bg-amber-600/30 text-amber-300 font-bold" : "text-slate-400"}`}
            >
              أ+
            </button>
          </div>

          {isAlreadySolved && (
            <span className="flex items-center gap-1 bg-emerald-500/15 border border-emerald-500/30 text-emerald-300 text-xs px-2.5 py-1 rounded-full font-semibold">
              <CheckCircle2 className="w-3.5 h-3.5" />
              محلولة بنجاح
            </span>
          )}
        </div>
      </div>

      {/* Case Header Card */}
      <div className="bg-gradient-to-br from-[#161f30] to-[#121824] border border-amber-900/40 rounded-2xl p-6 shadow-xl relative overflow-hidden">
        <div className="absolute top-0 left-0 w-32 h-32 bg-amber-500/5 rounded-full blur-3xl pointer-events-none" />

        <div className="flex flex-wrap items-center gap-2 mb-3">
          <span className="text-xs bg-amber-500/20 text-amber-300 border border-amber-500/30 px-2.5 py-1 rounded-lg font-bold">
            {storyCase.genre}
          </span>
          <span className="text-xs bg-slate-800 text-slate-300 border border-slate-700 px-2.5 py-1 rounded-lg font-medium flex items-center gap-1">
            <Clock className="w-3 h-3 text-amber-400" />
            استراحة {storyCase.estimatedMinutes} دقائق
          </span>
          <span className="text-xs bg-purple-500/15 text-purple-300 border border-purple-500/30 px-2.5 py-1 rounded-lg font-medium flex items-center gap-1">
            <BrainCircuit className="w-3 h-3" />
            {storyCase.cognitiveSkillTrained}
          </span>
          <span className="text-xs bg-slate-800 text-amber-400 border border-amber-800/40 px-2.5 py-1 rounded-lg">
            مستوى: {storyCase.difficulty}
          </span>
        </div>

        <h1 className="text-2xl sm:text-3xl font-bold font-novel text-amber-100 mb-2">
          {storyCase.title}
        </h1>
        <h2 className="text-base text-amber-400/90 font-medium mb-3">
          {storyCase.chapterTitle}
        </h2>
        <p className="text-slate-300 text-sm italic border-r-2 border-amber-500 pr-3">
          "{storyCase.synopsis}"
        </p>

        <div className="flex items-center gap-2 mt-4 text-xs text-slate-400">
          <MapPin className="w-3.5 h-3.5 text-amber-500" />
          <span>الموقع: {storyCase.location}</span>
        </div>
      </div>

      {/* Main Narrative Reading Canvas */}
      <div className="bg-[#121822] border border-slate-800/80 rounded-2xl p-6 sm:p-8 shadow-md">
        <div className="flex items-center justify-between mb-4 pb-3 border-b border-slate-800">
          <div className="flex items-center gap-2 text-amber-400 font-bold text-sm">
            <BookMarked className="w-4 h-4" />
            <span>وقائع الرواية وأحداث التحقيق</span>
          </div>
          <span className="text-xs text-slate-500">اقرأ بتأنٍ واستخرج التناقضات</span>
        </div>

        <div className={`font-novel text-slate-200 whitespace-pre-line tracking-wide ${getFontSizeClass()}`}>
          {storyCase.storyContent}
        </div>
      </div>

      {/* Suspects & Testimonies Section */}
      {storyCase.suspectsOrEntities && storyCase.suspectsOrEntities.length > 0 && (
        <div className="space-y-3">
          <div className="flex items-center gap-2 text-slate-200 font-bold text-sm">
            <UserCheck className="w-4 h-4 text-amber-400" />
            <span>إفادات الشهود والمشتبه بهم (قارن بين أقوالهم والواقع)</span>
          </div>

          <div className="grid grid-cols-1 md:grid-cols-3 gap-3">
            {storyCase.suspectsOrEntities.map((s, idx) => (
              <div 
                key={idx}
                className="bg-slate-900/80 border border-slate-800 hover:border-amber-800/40 rounded-xl p-4 transition-all"
              >
                <div className="flex items-center justify-between mb-2">
                  <h4 className="font-bold text-amber-200 text-sm">{s.name}</h4>
                  <span className="text-[11px] text-slate-400 bg-slate-800 px-2 py-0.5 rounded">
                    {s.role}
                  </span>
                </div>
                <p className="text-xs sm:text-sm text-slate-300 leading-relaxed font-novel italic">
                  "{s.statement}"
                </p>
              </div>
            ))}
          </div>
        </div>
      )}

      {/* Interactive Evidence Board */}
      <div className="space-y-3">
        <div className="flex items-center justify-between">
          <div className="flex items-center gap-2 text-slate-200 font-bold text-sm">
            <Search className="w-4 h-4 text-amber-400" />
            <span>لوحة الأدلة المادية (اضغط لفحص كل دليل بعناية)</span>
          </div>
          <span className="text-xs text-slate-400">
            تم فحص {Object.values(revealedClues).filter(Boolean).length} من {storyCase.clues.length}
          </span>
        </div>

        <div className="grid grid-cols-1 md:grid-cols-3 gap-3">
          {storyCase.clues.map((clue) => {
            const isRevealed = revealedClues[clue.id];
            return (
              <div
                key={clue.id}
                onClick={() => toggleClue(clue.id)}
                className={`cursor-pointer border rounded-xl p-4 transition-all select-none ${
                  isRevealed
                    ? "bg-amber-950/20 border-amber-600/50 shadow-md shadow-amber-900/10"
                    : "bg-slate-900/60 border-slate-800 hover:border-slate-700"
                }`}
              >
                <div className="flex items-center justify-between gap-2 mb-2">
                  <div className="flex items-center gap-2">
                    <span className="w-5 h-5 rounded-full bg-amber-500/20 text-amber-300 text-xs flex items-center justify-center font-bold">
                      !
                    </span>
                    <h4 className="font-semibold text-sm text-amber-100">{clue.title}</h4>
                  </div>
                  {isRevealed ? (
                    <ChevronUp className="w-4 h-4 text-amber-400" />
                  ) : (
                    <ChevronDown className="w-4 h-4 text-slate-500" />
                  )}
                </div>

                <p className="text-xs text-slate-300 mb-2 leading-relaxed">
                  {clue.detail}
                </p>

                {isRevealed && (
                  <div className="mt-3 pt-2.5 border-t border-amber-900/30 text-xs bg-amber-950/40 p-2.5 rounded-lg text-amber-200 font-medium">
                    <span className="font-bold text-amber-400 block mb-1">المغزى الاستنتاجي:</span>
                    {clue.significance}
                  </div>
                )}
              </div>
            );
          })}
        </div>
      </div>

      {/* Socratic AI Clue Helper */}
      <div className="bg-[#151c2a] border border-slate-800 rounded-xl p-4 flex flex-col sm:flex-row items-center justify-between gap-3">
        <div className="flex items-center gap-3">
          <div className="w-9 h-9 rounded-lg bg-amber-500/20 border border-amber-500/40 flex items-center justify-center text-amber-300">
            <Lightbulb className="w-5 h-5" />
          </div>
          <div>
            <h4 className="text-sm font-bold text-slate-200">تحتاج توجيهاً ذهنياً دون حرق الإجابة؟</h4>
            <p className="text-xs text-slate-400">تلميح سقراطي يرشد تفكيرك لاكتشاف التناقض بنفسك</p>
          </div>
        </div>

        <button
          onClick={handleFetchAiHint}
          disabled={isLoadingHint || !!revealedHint}
          className={`px-4 py-2 rounded-lg text-xs font-bold transition-all whitespace-nowrap ${
            revealedHint
              ? "bg-slate-800 text-slate-400 border border-slate-700"
              : "bg-amber-600/30 text-amber-300 hover:bg-amber-600/40 border border-amber-500/40"
          }`}
        >
          {isLoadingHint ? "جاري استنطاق المساعد..." : revealedHint ? "تم إظهار التلميح" : "طلب تلميح سقراطي"}
        </button>
      </div>

      {revealedHint && (
        <div className="bg-amber-950/30 border border-amber-600/40 rounded-xl p-4 text-xs sm:text-sm text-amber-200 animate-fadeIn flex items-start gap-3">
          <Sparkles className="w-4 h-4 text-amber-400 shrink-0 mt-0.5" />
          <div>
            <span className="font-bold block text-amber-300 mb-0.5">همسة المحقق الداخلي:</span>
            {revealedHint}
          </div>
        </div>
      )}

      {/* The Cognitive Puzzle Conundrum & Solution Box */}
      <div className="bg-gradient-to-b from-[#141b27] to-[#10151f] border-2 border-amber-600/40 rounded-2xl p-6 sm:p-8 space-y-6 shadow-2xl">
        <div className="flex items-center gap-3">
          <div className="w-10 h-10 rounded-xl bg-amber-500/20 border border-amber-500/40 flex items-center justify-center text-amber-300">
            <BrainCircuit className="w-6 h-6" />
          </div>
          <div>
            <span className="text-xs uppercase tracking-wider text-amber-400 font-bold">
              تحدي الاستنتاج واليقظة الذهنية
            </span>
            <h3 className="text-lg sm:text-xl font-bold font-novel text-amber-100">
              {storyCase.puzzleQuestion}
            </h3>
          </div>
        </div>

        {/* Hypotheses Options */}
        <div className="space-y-3">
          <p className="text-xs text-slate-400 font-medium">
            اختر الفرضية الأكثر تماسكاً منطقياً مع الأدلة:
          </p>

          <div className="space-y-2.5">
            {storyCase.hypotheses.map((hyp) => {
              const isSelected = selectedHypothesis?.id === hyp.id;
              return (
                <div
                  key={hyp.id}
                  onClick={() => handleSelectHypothesis(hyp)}
                  className={`p-4 rounded-xl border cursor-pointer transition-all ${
                    isSelected
                      ? hyp.isCorrect
                        ? "bg-emerald-950/40 border-emerald-500 text-emerald-100"
                        : "bg-red-950/40 border-red-500 text-red-100"
                      : "bg-slate-900/80 border-slate-800 hover:border-amber-700/50 text-slate-200"
                  }`}
                >
                  <div className="flex items-start gap-3">
                    <span className={`w-5 h-5 rounded-full flex items-center justify-center text-xs shrink-0 mt-0.5 ${
                      isSelected
                        ? hyp.isCorrect
                          ? "bg-emerald-500 text-slate-950 font-bold"
                          : "bg-red-500 text-white font-bold"
                        : "bg-slate-800 text-slate-400 border border-slate-700"
                    }`}>
                      {isSelected ? (hyp.isCorrect ? "✓" : "✗") : "○"}
                    </span>
                    <div className="space-y-1">
                      <p className="text-sm font-medium leading-relaxed">{hyp.text}</p>
                      {isSelected && (
                        <div className={`mt-3 pt-2 border-t text-xs font-sans leading-relaxed ${
                          hyp.isCorrect ? "border-emerald-800 text-emerald-300" : "border-red-800 text-red-300"
                        }`}>
                          <span className="font-bold block mb-1">
                            {hyp.isCorrect ? "تحليل العقل الثاقب:" : "مغالطة منطقية خفية:"}
                          </span>
                          {hyp.shortExplanation}
                        </div>
                      )}
                    </div>
                  </div>
                </div>
              );
            })}
          </div>
        </div>

        {/* Custom Deductive Theory Input (AI Evaluated) */}
        <div className="pt-4 border-t border-slate-800/80 space-y-3">
          <div className="flex items-center justify-between">
            <span className="text-xs font-bold text-amber-300 flex items-center gap-1.5">
              <Sparkles className="w-3.5 h-3.5" />
              أو اكتب استنتاجك الحر ليحلله الذكاء الاصطناعي:
            </span>
            <span className="text-[11px] text-slate-500">تقييم منطقي فوري</span>
          </div>

          <form onSubmit={handleSubmitCustomTheory} className="space-y-2">
            <textarea
              rows={3}
              value={customTheory}
              onChange={(e) => setCustomTheory(e.target.value)}
              placeholder="اكتب نظريتك بناءً على تفاصيل المطر والزجاج وأقوال الشهود..."
              className="w-full bg-slate-900 border border-slate-700 rounded-xl p-3 text-sm text-slate-100 placeholder:text-slate-500 focus:outline-none focus:border-amber-500 resize-none font-novel"
            />
            <button
              type="submit"
              disabled={isEvaluatingAi || !customTheory.trim()}
              className="w-full sm:w-auto px-5 py-2.5 rounded-xl bg-amber-600 hover:bg-amber-500 disabled:bg-slate-800 disabled:text-slate-600 text-slate-950 font-bold text-xs flex items-center justify-center gap-2 transition-colors"
            >
              {isEvaluatingAi ? (
                <>
                  <div className="w-3.5 h-3.5 border-2 border-slate-950 border-t-transparent rounded-full animate-spin" />
                  <span>جاري تحليل التماسك المنطقي لنظريتك...</span>
                </>
              ) : (
                <>
                  <Send className="w-3.5 h-3.5" />
                  <span>إرسال الاستنتاج لتقييم الذكاء الاصطناعي</span>
                </>
              )}
            </button>
          </form>

          {/* AI Custom Evaluation Banner */}
          {aiEvaluation && (
            <div className={`p-4 rounded-xl border mt-3 animate-fadeIn text-xs sm:text-sm ${
              aiEvaluation.isCorrect || aiEvaluation.score >= 70
                ? "bg-emerald-950/30 border-emerald-500/50 text-emerald-200"
                : "bg-amber-950/30 border-amber-600/50 text-amber-200"
            }`}>
              <div className="flex items-center justify-between mb-2">
                <span className="font-bold flex items-center gap-1.5">
                  <Sparkles className="w-4 h-4 text-amber-400" />
                  الحكم: {aiEvaluation.verdict} (درجة المنطق: {aiEvaluation.score}/100)
                </span>
                <span className="bg-amber-500/20 text-amber-300 px-2 py-0.5 rounded text-[11px] font-mono">
                  +{aiEvaluation.cognitivePointsEarned} نقطة يقظة
                </span>
              </div>
              <p className="leading-relaxed mb-2 font-novel text-slate-200">
                {aiEvaluation.feedback}
              </p>
              <div className="text-[11px] text-amber-300 font-sans border-t border-amber-800/40 pt-1.5 flex items-center gap-1">
                <BrainCircuit className="w-3 h-3" />
                <span>أثر التنشيط الذهني: {aiEvaluation.brainAlertnessBoost}</span>
              </div>
            </div>
          )}
        </div>
      </div>
    </div>
  );
};

