          })}
        </div>
      </div>

      {/* Socratic AI Clue Helper */}
      <div className="bg-[#151c2a] border border-slate-800 rounded-xl p-4 flex flex-col sm:flex-row items-center justify-between gap-3">
        <div className="flex items-center gap-3">
          <div className="w-9 h-9 rounded-lg bg-amber-500/20 border border-amber-500/40 flex items-center justify-center text-amber-300">
            <Lightbulb className="w-5 h-5" />
          </div>
