          </p>

          <div className="space-y-2.5">
            {storyCase.hypotheses.map((hyp) => {
              const isSelected = selectedHypothesis?.id === hyp.id;
              return (
                <div
                  key={hyp.id}
                  onClick={() => handleSelectHypothesis(hyp)}
                  className={`p-4 rounded-xl border cursor-pointer transition-all ${
                    isSelected
                      ? hyp.isCorrect
                        ? "bg-emerald-950/40 border-emerald-500 text-emerald-100"
                        : "bg-red-950/40 border-red-500 text-red-100"
                      : "bg-slate-900/80 border-slate-800 hover:border-amber-700/50 text-slate-200"
                  }`}
                >
                  <div className="flex items-start gap-3">
                    <span className={`w-5 h-5 rounded-full flex items-center justify-center text-xs shrink-0 mt-0.5 ${
                      isSelected
                        ? hyp.isCorrect
                          ? "bg-emerald-500 text-slate-950 font-bold"
                          : "bg-red-500 text-white font-bold"
                        : "bg-slate-800 text-slate-400 border border-slate-700"
                    }`}>
                      {isSelected ? (hyp.isCorrect ? "✓" : "✗") : "○"}
                    </span>
                    <div className="space-y-1">
                      <p className="text-sm font-medium leading-relaxed">{hyp.text}</p>
                      {isSelected && (
                        <div className={`mt-3 pt-2 border-t text-xs font-sans leading-relaxed ${
