import React, { useState } from "react";
import { StoryCase } from "../types";
import { 
  Clock, 
  MapPin, 
  BrainCircuit, 
  CheckCircle2, 
  Sparkles, 
  BookOpen, 
  Filter, 
  Compass,
  ArrowLeft
} from "lucide-react";

interface CasesListProps {
  cases: StoryCase[];
  solvedCaseIds: Set<string>;
  onSelectCase: (c: StoryCase) => void;
  onOpenAiGenerator: () => void;
  onOpenQuickGym: () => void;
}

export const CasesList: React.FC<CasesListProps> = ({
  cases,
  solvedCaseIds,
  onSelectCase,
  onOpenAiGenerator,
  onOpenQuickGym,
}) => {
  const [filterDifficulty, setFilterDifficulty] = useState<string>("all");

  const filteredCases = cases.filter((c) => {
    if (filterDifficulty === "all") return true;
    return c.difficulty === filterDifficulty;
  });

  return (
    <div className="max-w-6xl mx-auto px-4 sm:px-6 py-6 space-y-8 animate-fadeIn">
      {/* Hero Banner tailored for the laptop worker */}
