          const isSolved = solvedCaseIds.has(story.id);

          return (
            <div
              key={story.id}
              onClick={() => onSelectCase(story)}
              className="group bg-[#131926] hover:bg-[#161e2e] border border-slate-800 hover:border-amber-700/50 rounded-2xl p-5 shadow-lg transition-all cursor-pointer flex flex-col justify-between relative overflow-hidden"
