                </div>
              )}

              <div className="space-y-3">
                <div className="flex flex-wrap items-center gap-2">
                  <span className="text-[11px] bg-amber-500/15 text-amber-300 border border-amber-500/30 px-2 py-0.5 rounded font-medium">
                    {story.genre}
                  </span>
                  <span className="text-[11px] bg-slate-800 text-slate-300 px-2 py-0.5 rounded flex items-center gap-1">
                    <Clock className="w-3 h-3 text-amber-400" />
                    {story.estimatedMinutes} دقائق
                  </span>
                  <span className="text-[11px] bg-slate-800 text-slate-300 px-2 py-0.5 rounded">
                    مستوى: {story.difficulty}
                  </span>
                  {isSolved && (
                    <span className="text-[11px] bg-emerald-500/20 text-emerald-300 border border-emerald-500/40 px-2 py-0.5 rounded flex items-center gap-1 font-bold">
                      <CheckCircle2 className="w-3 h-3" />
                      محلولة
                    </span>
                  )}
                </div>

                <div>
                  <h4 className="text-lg font-bold font-novel text-amber-100 group-hover:text-amber-300 transition-colors">
                    {story.title}
                  </h4>
                  <div className="text-xs text-amber-400/80 font-medium">
                    {story.chapterTitle}
                  </div>
                </div>

                <p className="text-xs sm:text-sm text-slate-300 font-novel line-clamp-2 leading-relaxed">
                  "{story.synopsis}"
                </p>

                <div className="flex items-center gap-1.5 text-xs text-purple-300/90 pt-1">
                  <BrainCircuit className="w-3.5 h-3.5 text-purple-400" />
                  <span>المهارة الذهنية: {story.cognitiveSkillTrained}</span>
                </div>
              </div>

              <div className="mt-4 pt-3 border-t border-slate-800/80 flex items-center justify-between text-xs">
                <span className="text-slate-400 flex items-center gap-1">
                  <MapPin className="w-3 h-3 text-amber-500" />
                  {story.location}
                </span>

                <span className="text-amber-400 font-bold group-hover:translate-x-[-4px] transition-transform flex items-center gap-1">
                  <span>فتح ملف القضية</span>
                  <ArrowLeft className="w-3.5 h-3.5" />
                </span>
              </div>
            </div>
          );
        })}
      </div>
    </div>
  );
};

